package org.mulino.verification.nativeclient;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import org.mulino.verification.*;
import org.mulino.verification.actual.*;
import org.mulino.verification.modelbinding.*;
import java.nio.file.*;
import java.net.http.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Selected public HTTP inputs and synthetic originals; no case/corpus oracle or scenario runner is loaded. */
final class NativeSourceFlowProbe {
    final Path root;final ActualConfiguration config;final ObjectNode bindings=Json.object();
    final NativeIntegrationEvidence evidence;final NativeMcpTransport transport;final NativePhysicalObserver observer;
    JsonNode actor,actors,scope;String organizationAlias;String now="2026-10-07T09:00:02Z";
    NativeSourceFlowProbe(Path root,ActualConfiguration config)throws Exception{
        this.root=root;this.config=config;evidence=new NativeIntegrationEvidence(root);transport=new NativeMcpTransport(config,evidence);observer=new NativePhysicalObserver(config,evidence);
        var fixture=(ObjectNode)Json.read(root.resolve("verification/actual/s4/fixture.json"));var bundle=Json.object().put("fixtureHash",Json.sha256(root.resolve("verification/actual/s4/fixture.json"))).put("organizationExternalAlias","independent-source-"+UUID.randomUUID());bundle.set("fixture",fixture);var installation=new FixtureInstaller(config).install(bundle);bindings.setAll((ObjectNode)installation.path("aliasMap"));actors=fixture.path("actors");organizationAlias=bundle.path("organizationExternalAlias").asText();actor=actors.path("reader").deepCopy();((ObjectNode)actor).put("organizationAlias",organizationAlias);scope=Json.object().put("organizationId",bindings.path("ORG").asText()).put("installationId",UUID.randomUUID().toString()).put("caseId","DIRECT-SOURCE-PROBE").put("turnId","turn-1");
        var clock=HttpRequest.newBuilder(config.baseUri().resolve("/__verification/runtime/clock")).header("Content-Type","application/json").header("Authorization","Bearer "+new JwtSigner(config).sign(actor)).POST(HttpRequest.BodyPublishers.ofString(Json.object().put("instant",now).toString())).build();var response=HttpClient.newHttpClient().send(clock,HttpResponse.BodyHandlers.ofString());assertEquals(200,response.statusCode());evidence.save("source-probe-clock",Json.parse(response.body()));
    }
    void selected(String file,Set<String> selected)throws Exception{var found=new HashSet<String>();for(JsonNode action:Json.read(root.resolve(file)).path("actions"))if(selected.contains(action.path("id").asText())){found.add(action.path("id").asText());execute(action);}assertEquals(selected,found,"Unknown selected direct HTTP input");}
    void until(String file,String last)throws Exception{boolean found=false;for(JsonNode action:Json.read(root.resolve(file)).path("actions")){execute(action);if(action.path("id").asText().equals(last)){found=true;break;}}assertTrue(found);}
    void execute(JsonNode action)throws Exception{
        String id=Json.required(action,"id"),type=Json.required(action,"type");
        if(type.equals("uuid")){bindings.put(Json.required(action,"alias"),UUID.randomUUID().toString());return;}
        if(type.equals("original")){var fixture=resolve(action.path("fixture"));var bundle=Json.object().put("fixturePhase","S4_ORIGINAL").put("fixtureHash",Json.sha256Text(fixture.toString()));bundle.set("fixture",fixture);bundle.set("binding",resolve(action.path("binding")));var installed=new FixtureInstaller(config).install(bundle);assertEquals(installed.path("sourceContentSha256"),installed.path("blobReadbackSha256"));installed.path("aliasMap").fields().forEachRemaining(e->bindings.set(id+"."+e.getKey(),e.getValue()));bindings.set(id+".hash",installed.path("sourceContentSha256"));evidence.save("source-original",installed);return;}
        assertTrue(Set.of("command","lost-response","query").contains(type),"Focused probe does not execute "+type);String capability=Json.required(action,"capability");var request=resolve(action.path("request"));if(capability.equals("assessGoal")){var current=capture();var revisions=new ArrayList<JsonNode>();for(JsonNode work:current.path("rawRows").path("mulino_work_read_Works"))if(work.path("ID").equals(request.path("slots").path("workId")))revisions.add(work.path("revision"));assertEquals(1,revisions.size());((ObjectNode)request).set("expectedRevision",revisions.getFirst());evidence.save("actual-assessment-revision-input",current);}ObjectNode effectBefore=Set.of("prepareRegulatoryProcedure","receiveProvisional").contains(capability)?capture():null;var executionActor=(ObjectNode)actors.path(action.path("actor").asText("reader")).deepCopy();executionActor.put("organizationAlias",organizationAlias);var wire=transport.send("turn-1/agent-"+id,"tools/call",capability,request,executionActor,scope);assertEquals(200,wire.status(),id);JsonNode response=wire.businessResponse();if(!type.equals("query"))assertTrue(Set.of("APPLIED","ACCEPTED_PENDING_EXTERNAL").contains(response.path("outcome").asText()),id+": "+response);else assertTrue(response.has("snapshotRevision"),id+": "+response);
        if(effectBefore!=null){var after=capture();var effects=NativeCausalEffects.observe(effectBefore,after,NativeCausalEffects.wires(root.resolve(after.path("snapshot").path("artifactRef").asText()).getParent()));assertTrue(effects.path("complete").asBoolean(),effects.toString());boolean physicalClass=false;for(JsonNode effect:effects.path("rows")){assertEquals(response.path("commandId"),effect.path("commandId"));if(capability.equals("prepareRegulatoryProcedure")){assertNotEquals("RECORD_SUBMISSION",effect.path("operation").asText());if(effect.path("operation").asText().equals("PREPARE_REGULATORY_PROCEDURE"))physicalClass=true;}else{assertTrue(effect.path("measurements").isEmpty());if(effect.path("operation").asText().equals("RECEIVE_PROVISIONAL"))physicalClass=true;}}assertTrue(physicalClass);evidence.save("source-causal-"+capability,effects);}
        action.path("bind").fields().forEachRemaining(e->{JsonNode value=response.at(e.getValue().asText());assertFalse(value.isMissingNode(),id+" response binding");bindings.set(e.getKey(),value);});
        if(id.equals("receipt60-provisional")){var captured=capture();assertTrue(captured.path("rawRows").path("segments").isEmpty(),"Provisional source cannot create physical stock");assertFalse(captured.path("rawRows").path("mulino_trade_receipt_Observations").isEmpty());var duties=NativePhysicalFacts.obligations(captured.path("rawRows"),now,now,now);assertTrue(duties.path("complete").asBoolean(),duties.toString());assertFalse(duties.path("rows").isEmpty());for(JsonNode duty:duties.path("rows"))for(String key:List.of("ownerRef","supervisorId","nextAction","nextCheckAt","rootId","scopeId"))assertTrue(duty.hasNonNull(key),key);evidence.save("provisional-current-human-responsibility",duties);evidence.save("provisional-physical-zero",captured);}
    }
    ObjectNode parameters(){var p=Json.object().put("authorityAt",now).put("actorId",bindings.path("reader").asText());p.set("scope",scope);p.set("businessScope",Json.object().put("itemId",bindings.path("P").asText()));p.set("bindings",Json.object());return p;}
    ObjectNode capture()throws Exception{return observer.capture(scope,now,now);}
    void revision(String operation,String id,JsonNode readScope)throws Exception{
        var query=Json.object().put("asOf",now).put("knownAt",now);query.set("scope",readScope);if(id!=null)query.put("id",id);var reply=transport.send("turn-1/revision-"+operation,"tools/call",operation,query,actor,scope);assertTrue(reply.businessResponse().has("snapshotRevision"),reply.response().toString());var captured=capture();var projection=query.deepCopy();projection.remove(List.of("asOf","knownAt"));projection.put("operation",operation);var proof=Json.object().put("recipe",BusinessProjectionRecipes.ID).put("version",BusinessProjectionRecipes.VERSION).put("actorId",bindings.path("reader").asText());proof.set("request",projection);proof.set("parameters",parameters());proof.set("documents",captured.path("sourceDocuments"));var computed=BusinessProjectionRecipes.compute(captured,proof);
        var diagnostic=evidence.base("DIRECT_SOURCE_HTTP_PG_REVISION",scope);diagnostic.set("request",query);diagnostic.set("response",reply.businessResponse());diagnostic.set("recomputedWorld",computed.world());diagnostic.set("capture",captured);evidence.save("source-revision-"+operation,diagnostic);assertEquals(reply.businessResponse().path("snapshotRevision").asText(),computed.revision(),"Source-backed "+operation+" revision differs");
        var independent=NativeProjectionObserver.prove(captured,projection,bindings.path("reader").asText(),parameters(),evidence);captured.set("projectionRevisionProof",independent);var artifact=evidence.save("source-projection-contract",captured);var envelope=captured.deepCopy();envelope.put("snapshotRevision",computed.revision());((ObjectNode)envelope.path("snapshot")).put("readMode","RESULT_REVISION").put("artifactRef",artifact.path("path").asText());var requested=Json.object().put("asOf",now).put("knownAt",now).put("snapshotRef",computed.revision()).put("projectionActorId",bindings.path("reader").asText());requested.set("scope",scope);requested.set("projectionRequest",projection);requested.set("observationScope",parameters());ProjectionRevisionObservation.validateArtifact(new ContractValidator(root),envelope,requested);
        var wrongScope=requested.deepCopy();((ObjectNode)wrongScope.path("observationScope").path("scope")).put("turnId","copied-turn");assertThrows(IllegalArgumentException.class,()->ProjectionRevisionObservation.validateArtifact(new ContractValidator(root),envelope,wrongScope));
    }
    void intakeHistoryProof()throws Exception {
        // A new explicitly synthetic SQL intake fixture; the existing trigger binds its immutable event scope.
        try(var c=java.sql.DriverManager.getConnection(config.jdbcUrl(),config.username(),config.password())){
            c.setAutoCommit(false);try(var clock=c.prepareStatement("SELECT set_config('mulino.recovery_recorded_at',?,true)")){clock.setString(1,now);clock.execute();}
            String sql="INSERT INTO mulino_runtime_IntakeRecoveries(organizationId,ID,eventId,sourceProfileId,intakeOwnerId,supervisorId,nextAction,nextCheckAt,state,revision,fencingToken,attempts) SELECT organizationId,ID,eventId,sourceProfileId,intakeOwnerId,supervisorId,nextAction,nextCheckAt,'PENDING',0,0,0 FROM mulino_evidence_InboxRecords WHERE organizationId=? AND ID=?";
            try(var statement=c.prepareStatement(sql)){statement.setString(1,bindings.path("ORG").asText());statement.setString(2,bindings.path("receipt60.inbox").asText());assertEquals(1,statement.executeUpdate());}c.commit();
        }
        var captured=capture();var duties=NativePhysicalFacts.obligations(captured.path("rawRows"),now,now,now);assertTrue(duties.path("complete").asBoolean(),duties.toString());boolean found=false;for(JsonNode duty:duties.path("rows"))if(duty.path("kind").asText().equals("INTAKE_RECONCILIATION")){found=true;assertEquals(bindings.path("reader"),duty.path("ownerRef"));assertEquals(bindings.path("supervisor"),duty.path("supervisorId"));assertTrue(duty.path("historyComplete").asBoolean());assertFalse(duty.path("scopeRef").asText().isBlank());assertFalse(duty.path("nextAction").asText().isBlank());java.time.Instant.parse(duty.path("nextCheckAt").asText());}assertTrue(found);evidence.save("actual-synthetic-intake-immutable-history",captured);evidence.save("actual-intake-human-responsibility",duties);
        for(String mutation:List.of("historyComplete","scopeComplete","missing-history")){var changed=captured.path("rawRows").deepCopy();for(JsonNode h:changed.path("mulino_runtime_RecoveryObservationHistory"))if(h.path("sourceTable").asText().equals("mulino_runtime_intakerecoveries"))((ObjectNode)h).set(mutation.equals("missing-history")?"recordedAt":mutation,mutation.equals("missing-history")?Json.MAPPER.getNodeFactory().textNode("2026-10-07T09:00:03Z"):Json.MAPPER.getNodeFactory().booleanNode(false));assertFalse(NativePhysicalFacts.obligations(changed,now,now,now).path("complete").asBoolean(),mutation);}
    }
    JsonNode resolve(JsonNode node){if(node.isTextual()&&node.asText().startsWith("$")){String key=node.asText().substring(1);assertTrue(bindings.has(key),"Unbound actual input "+key);return bindings.path(key).deepCopy();}if(node.isObject()){var result=Json.object();node.fields().forEachRemaining(e->result.set(e.getKey(),resolve(e.getValue())));return result;}if(node.isArray()){var result=Json.array();node.forEach(n->result.add(resolve(n)));return result;}return node.deepCopy();}
}
